// Extrae remitente y texto del payload de WhatsApp Cloud API
const body = $('Entra mensaje WhatsApp').first().json.body || $('Entra mensaje WhatsApp').first().json;
const msg = body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!msg || msg.type !== 'text') { return []; } // ignora estados/no-texto
return [{ json: {
  from: msg.from,
  text: msg.text.body,
  WHATSAPP_TOKEN: $json.WHATSAPP_TOKEN,
  PHONE_ID: $json.PHONE_ID,
  OPENAI_KEY: $json.OPENAI_KEY,
  NEGOCIO: $json.NEGOCIO
}}];
